This autoload accumulates per-instance state from multiple players in a multiplayer game. Refactor:
```gdscript
# MultiplayerState.gd (autoload)
var player_scores: Dictionary = {}
var player_positions: Dictionary = {}
var player_healths: Dictionary = {}

func register_player(pid: int, pos: Vector2, hp: int) -> void:
    player_scores[pid] = 0
    player_positions[pid] = pos
    player_healths[pid] = hp

func update_score(pid: int, points: int) -> void:
    player_scores[pid] = player_scores.get(pid, 0) + points

func update_position(pid: int, pos: Vector2) -> void:
    player_positions[pid] = pos

func get_leaderboard() -> Array:
    return player_scores.keys().map(func k: return {"id": k, "score": player_scores[k]})
```
